import { getSiteSettings } from "@/lib/settings";

const defaultMessage = "Hola! Me contacto desde el sitio web www.unomasunoarquitectos.com.ar. Me gustaría consultar lo siguiente:";

function digits(phone: string) { return phone.replace(/\D/g, ""); }
function wa(phone: string, message = defaultMessage) {
  return `https://wa.me/${digits(phone)}?text=${encodeURIComponent(message)}`;
}

export default async function Footer() {
  const settings = await getSiteSettings();
  const phones = (settings.phone || "").split("|").map((p) => p.trim()).filter(Boolean);

  return (
    <footer className="site-footer">
      <div className="site-container footer-grid">
        <div className="footer-logo-wrap">
          <img src="/brand/footer-logo.png" alt="UNO MÁS UNO Arquitectos" className="footer-logo-img" />
        </div>

        <nav className="footer-nav" aria-label="Navegación de pie">
          <a href="/">Proyectos</a>
          <a href="/nosotros">Nosotros</a>
          <a href="/academia">Academia</a>
          <a href="/menciones">Menciones</a>
        </nav>

        <div className="footer-contact">
          <h3>Contacto</h3>
          <div className="footer-socials">
            {settings.instagram_url && <a href={settings.instagram_url} target="_blank" rel="noreferrer">Instagram</a>}
            {settings.facebook_url && <a href={settings.facebook_url} target="_blank" rel="noreferrer">Facebook</a>}
          </div>
          {phones.length > 0 && (
            <p>Teléfono: {phones.map((phone, index) => (
              <span key={phone}>{index > 0 ? " | " : ""}<a href={wa(phone)} target="_blank" rel="noreferrer">{phone}</a></span>
            ))}</p>
          )}
          {settings.email && <p>Mail: <a href={`mailto:${settings.email}`}>{settings.email}</a></p>}
        </div>
      </div>

      <div className="site-container footer-bottom">
        <span>© {new Date().getFullYear()} UNO MÁS UNO Arquitectos</span>
        <span>Sitio web desarrollado con &lt;3 <a href={wa("+54 9 261 2434819", "Hola! Me contacto desde el sitio web de UNO MÁS UNO Arquitectos.")} target="_blank" rel="noreferrer">Pantech</a></span>
      </div>
    </footer>
  );
}
